ize:12px}.run-stats{display:grid;gap:9px;text-align:right;font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.12em;color:#91c8a4}.run-stats strong{color:#858b9d;font-size:9px;font-weight:400}.status-dot,.live-label i{display:inline-block;width:6px;height:6px;background:#81c69b;border-radius:50%;box-shadow:0 0 8px #81c69b;vertical-align:1px;margin-right:5px}.game-layout{display:grid;grid-template-columns:244px minmax(420px,1fr) 260px;gap:15px;align-items:stretch}.panel{background:linear-gradient(160deg,#1c2030,#171b28);border:1px solid #34394b;border-radius:12px;box-shadow:var(--shadow)}.hero-panel{padding:18px 17px 15px}.panel-kicker{display:flex;align-items:center;justify-content:space-between;font-size:9px;letter-spacing:.12em}.level-badge{background:#302b37;color:#e8bc72;border:1px solid #4d4140;border-radius:4px;padding:4px 6px;font-size:9px}.hero-art{position:relative;height:160px;margin:17px -2px 15px;overflow:hidden;border-radius:8px;background:radial-gradient(ellipse at 50% 80%,#654a44 0,#382d38 35%,#242438 70%,#1d2131 100%)}.hero-art:after{content:"";position:absolute;inset:auto 0 0;height:40%;background:linear-gradient(transparent,#121622);z-index:3}.art-glow{position:absolute;width:135px;height:135px;left:50%;top:20px;transform:translateX(-50%);background:#d29c6250;border-radius:50%;filter:blur(30px)}.hero-sigil{position:absolute;top:17px;left:50%;transform:translateX(-50%);font-size:42px;color:#f0d39a66}.hero-figure{position:absolute;left:50%;bottom:16px;width:86px;height:118px;transform:translateX(-50%);z-index:2}.hero-head{position:absolute;z-index:3;top:7px;left:34px;width:23px;height:28px;border-radius:45% 45% 42% 42%;background:linear-gradient(90deg,#7e5146,#cb8e6e 55%,#895449);box-shadow:inset -5px 0 #533a3f}.hero-cape{position:absolute;top:32px;left:12px;width:66px;height:84px;background:linear-gradient(110deg,#a34043,#512b3b 74%);clip-path:polygon(25% 0,75% 0,100% 100%,50% 82%,0 100%)}.hero-body{position:absolute;z-index:2;top:31px;left