        if (state.mp < 8) return;
        state.mp -= 8; damage = Math.round(state.power * 1.45 + 10 + Math.random() * 5);
        state.burn = 2; log(`Ember Burst scorches for ${damage}! The foe is burning.`); beep(480); break;
