*{box-sizing:border-box}
 :root{color-scheme:dark;--bg:#10131e;--panel:#191d2b;--panel2:#202536;--line:#34394c;--muted:#9ba2b8;--cream:#f4ead7;--gold:#e8bc72;--red:#e77570;--green:#88c9a1;--blue:#8eb7ef;--purple:#c3a2f1;--shadow:0 20px 70px #080a10a6}
body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 48% -15%,#343044 0,#171a28 42%,#0e111a 100%);color:var(--cream);font-family:Manrope,system-ui,sans-serif;font-size:14px}
button{font:inherit;color:inherit}
button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
.app{max-width:1450px;margin:auto;padding:28px 34px 32px}
.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:23px}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{width:42px;height:42px;border:1px solid #806c54;border-radius:13px;display:grid;place-items:center;background:linear-gradient(145deg,#392d31,#201b27);font-size:21px;box-shadow:inset 0 1px #ffffff18}
.brand-name{font-family:'Playfair Display',serif;font-weight:700;font-size:20px;letter-spacing:.03em}
.brand-sub{font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.18em;color:#a6a2a9;font-size:9px;margin-top:3px}
.top-meta{display:flex;align-items:center;gap:10px}
.top-pill{display:flex;align-items:center;gap:7px;padding:8px 12px;border:1px solid #34394a;background:#171b28;border-radius:99px;color:#d4d0ca;font-size:12px}
.top-pill strong{color:var(--gold);font-family:'DM Mono',monospace}
.sound-button{width:37px;height:37px;border:1px solid #34394a;background:#171b28;border-radius:50%;color:#c3a2f1;cursor:pointer}
.intro{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:23px}
.eyebrow,.panel-kicker{font-family:'DM Mono',monospace;color:#aaa9b5;font-size:10px;letter-spacing:.15em;font-weight:500}
.intro h1{font-family:'Playfair Display',serif;font-size:34px;letter-spacing:-.03em;margin:7px 0 4px;font-weight:600}
.intro h1 em{color:var(--gold);font-style:normal}
.intro p{margin:0;color:#9da2b2;font-size:12px}
.run-stats{display:grid;gap:8px;text-align:right;font:9px 'DM Mono',monospace;letter-spacing:.08em;color:#abb0bd}
.run-stats strong{color:var(--gold);font-weight:500}
.status-dot,.live-label i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#83c69b;margin-right:5px;box-shadow:0 0 10px #83c69b88}
.game-layout{display:grid;grid-template-columns:235px minmax(430px,1fr) 250px;gap:15px;align-items:start}
.panel{background:linear-gradient(145deg,#1d2130,#171b27);border:1px solid #34394a;border-radius:10px;box-shadow:0 12px 35px #080a102e}
.hero-panel{padding:17px}
.hero-panel .panel-kicker{display:flex;justify-content:space-between;align-items:center}
.level-badge{color:var(--gold);border:1px solid #594d3e;border-radius:4px;padding:4px 6px;font-size:8px}
.hero-art{height:170px;margin:17px 0 13px;border:1px solid #3b3544;border-radius:7px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,#704a42 0,#2c2632 37%,#171a27 78%)}
.art-glow{position:absolute;width:130px;height:130px;border-radius:50%;left:50%;top:32px;transform:translateX(-50%);background:#d7825b1c;filter:blur(19px)}
.hero-sigil{position:absolute;left:50%;top:15px;transform:translateX(-50%);color:#e8bc7255;font-size:32px}
.hero-figure{position:absolute;inset:40px 0 0;display:flex;justify-content:center}
.hero-head{position:absolute;z-index:2;top:7px;width:28px;height:34px;border-radius:45% 45% 35% 35%;background:linear-gradient(90deg,#d9b795,#8b685f);box-shadow:0 0 10px #e8bc7244}
.hero-cape{position:absolute;top:27px;width:86px;height:94px;background:linear-gradient(100deg,#382c3a,#70504b 50%,#302733);clip-path:polygon(25% 0,75% 0,100% 100%,0 100%)}
.hero-body{position:absolute;top:35px;width:51px;height:67px;background:linear-gradient(90deg,#5b4a4b,#b38a69,#4b4148);clip-path:polygon(22% 0,78% 0,100% 100%,0 100%)}
.hero-blade{position:absolute;z-index:3;top:31px;left:calc(50% + 33px);font-size:53px;color:#e3dfd1;text-shadow:0 0 10px #dce8f455;transform:rotate(12deg)}
.art-caption{position:absolute;bottom:9px;left:0;right:0;text-align:center;font:8px 'DM Mono',monospace;letter-spacing:.2em;color:#d2b890}
.hero-name-row{display:flex;justify-content:space-between;align-items:center}
.hero-name-row h2{font:600 19px 'Playfair Display',serif;margin:0 0 3px}
.hero-class{color:#a6a9b5;font-size:10px}
.class-icon{color:var(--gold);font-size:19px}
.hero-details{display:grid;grid-template-columns:repeat(3,1fr);margin:15px 0;padding:12px 0;border-top:1px solid #303546;border-bottom:1px solid #303546}
.hero-details div{display:grid;gap:6px}
.hero-details span,.inventory-title,.tower-progress span,.journal-foot{font:8px 'DM Mono',monospace;letter-spacing:.1em;color:#9b9fb0}
.hero-details strong{font:13px 'DM Mono',monospace;color:#eee3d2}
.inventory-title{display:flex;justify-content:space-between;margin-bottom:9px}
.inventory-title span{color:#737b8f}
.item-row{display:flex;align-items:center;gap:9px;padding:7px 0;color:#c5c6cf;font-size:10px}
.item-row strong{margin-left:auto;font:10px 'DM Mono',monospace;color:var(--gold)}
.item-icon{display:grid;place-items:center;width:22px;height:22px;border-radius:5px;background:#302b35;font-size:12px}
.item-icon.potion{color:#e77570}
.item-icon.ether{color:#c3a2f1}
.battle-panel{padding:18px}
.battle-heading{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}
.battle-heading h2{font:600 22px 'Playfair Display',serif;margin:5px 0 0}
.turn-badge{white-space:nowrap;border:1px solid #365543;background:#1a3028;color:#8fd2a1;border-radius:99px;padding:7px 9px;font:8px 'DM Mono',monospace;letter-spacing:.06em}
.turn-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:currentColor;margin-right:4px}
.turn-badge.enemy-turn{color:#e78b7e;border-color:#65403c;background:#352322}
.combat-vitals{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0 0 13px;padding:10px 12px;border:1px solid #34394b;border-radius:7px;background:#151925}
.combat-vitals .vitals{margin:0;min-width:0}
.combat-vitals .vital-head{font-size:9px}
.vital-head,.enemy-vital-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;font:9px 'DM Mono',monospace;letter-spacing:.05em;color:#aaaebe}
.vital-head strong,.enemy-vital-head strong{color:#ede2d0;font-weight:500}
.bar,.shop-bar{height:6px;background:#303342;border-radius:99px;overflow:hidden}
.bar-fill,.shop-bar i{display:block;width:100%;height:100%;border-radius:inherit;transition:width .25s ease}
.hp-fill,.shop-hp-fill{background:linear-gradient(90deg,#ac484c,#eb8175)}
.mp-fill,.shop-mp-fill{background:linear-gradient(90deg,#6558b3,#b397ed)}
.arena{height:250px;position:relative;overflow:hidden;border:1px solid #383a4c;border-radius:7px;background:radial-gradient(ellipse at 50% 60%,#49364b 0,#242336 43%,#151923 100%)}
.arena-vignette{position:absolute;inset:0;background:linear-gradient(180deg,#14172222,#17172244 75%,#10131eaa)}
.moon{position:absolute;right:17%;top:24px;width:49px;height:49px;border-radius:50%;background:#e5c5971c;box-shadow:0 0 35px #d9b57a23}
.spire{position:absolute;color:#171924;text-shadow:0 0 1px #9d829744}
.spire-back{font-size:110px;left:11%;top:36px}
.spire-mid{font-size:145px;right:9%;top:30px}
.spire-front{font-size:175px;left:39%;top:23px;color:#171925}
.arena-floor{position:absolute;left:-10%;right:-10%;height:85px;bottom:-38px;border-radius:50%;background:#171923;border-top:1px solid #6b52604d}
.enemy-wrap{position:absolute;z-index:2;left:50%;top:39px;transform:translateX(-50%);width:145px;height:160px;display:grid;place-items:center;transition:filter .2s}
.enemy-wrap.boss{transform:translateX(-50%) scale(1.13)}
.enemy-wrap.hit{animation:enemyHit .24s}
.enemy-aura{position:absolute;width:105px;height:105px;border-radius:50%;background:#d0646222;filter:blur(10px);animation:auraPulse 2.4s infinite}
.enemy-emoji{position:relative;font-size:82px;filter:drop-shadow(0 10px 7px #0009);animation:floatEnemy 2.8s ease-in-out infinite}
.enemy-shadow{position:absolute;bottom:3px;width:90px;height:17px;border-radius:50%;background:#08090dbb;filter:blur(4px)}
.arena-label{position:absolute;z-index:3;left:12px;right:12px;bottom:11px;display:flex;justify-content:space-between;align-items:center;font:8px 'DM Mono',monospace;color:#a5a7b3;letter-spacing:.07em}
