* { box-sizing:border-box }
:root { color-scheme:dark;--bg:#10131e;--panel:#191d2b;--panel2:#202536;--line:#34394c;--muted:#9ba2b8;--cream:#f4ead7;--gold:#e8bc72;--red:#e77570;--green:#88c9a1;--blue:#8eb7ef;--purple:#c3a2f1;--shadow:0 20px 70px #080a10a6 }
body { margin:0;min-height:100vh;background:radial-gradient(ellipse at 48% -15%,#343044 0,#171a28 42%,#0e111a 100%);color:var(--cream);font-family:Manrope,system-ui,sans-serif;font-size:14px }
button { font:inherit;color:inherit }
