* {
  box-sizing:border-box}
 :root {
  color-scheme:dark;--bg:#10131e;--panel:#191d2b;--panel2:#202536;--line:#34394c;--muted:#9ba2b8;--cream:#f4ead7;--gold:#e8bc72;--red:#e77570;--green:#88c9a1;--blue:#8eb7ef;--purple:#c3a2f1;--shadow:0 20px 70px #080a10a6}
body {
  margin:0;min-height:100vh;background:radial-gradient(ellipse at 48% -15%,#343044 0,#171a28 42%,#0e111a 100%);color:var(--cream);font-family:Manrope,system-ui,sans-serif;font-size:14px}
button {
  font:inherit;color:inherit}
button:focus-visible {
  outline:2px solid var(--gold);outline-offset:3px}
.app {
  max-width:1450px;margin:auto;padding:28px 34px 32px}
.topbar {
  display:flex;align-items:center;justify-content:space-between;margin-bottom:23px}
.brand {
  display:flex;align-items:center;gap:12px}
.brand-mark {
  width:42px;height:42px;border:1px solid #806c54;border-radius:13px;display:grid;place-items:center;background:linear-gradient(145deg,#392d31,#201b27);font-size:21px;box-shadow:inset 0 1px #ffffff18}
.brand-name {
  font-family:'Playfair Display',serif;font-weight:700;font-size:20px;letter-spacing:.03em}
.brand-sub {
  font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.18em;color:#a6a2a9;font-size:9px;margin-top:3px}
.top-meta {
  display:flex;align-items:center;gap:10px}
.top-pill {
  display:flex;align-items:center;gap:7px;padding:8px 12px;border:1px solid #34394a;background:#171b28;border-radius:99px;color:#d4d0ca;font-size:12px}
.top-pill strong {
  color:var(--gold);font-family:'DM Mono',monospace}
.sound-button {
  width:37px;height:37px;border:1px solid #34394a;background:#171b28;border-radius:50%;color:#c3a2f1;cursor:pointer}
.intro {
  display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:23px}
.eyebrow,.panel-kicker {
  font-family:'DM Mono',monospace;color:#aaa9b5;font-size:10px;letter-spacing:.15em;font-weight:500}
.intro h1 {
  font-family:'Playfair Display',serif;font-size:34px;letter-spacing:-.03em;margin:7px 0 4px;font-weight:600}
.intro h1 em {
  color:var(--gold);font-style:normal}
.intro p {
  margin:0;color:#9da2b2;font-size:12px}
.run-stats {
  display:grid;gap:8px;text-align:right;font:9px 'DM Mono',monospace;letter-spacing:.08em;color:#abb0bd}
.run-stats strong {
  color:var(--gold);font-weight:500}
.status-dot,.live-label i {
  display:inline-block;width:6px;height:6px;border-radius:50%;background:#83c69b;margin-right:5px;box-shadow:0 0 10px #83c69b88}
.game-layout {
  display:grid;grid-template-columns:235px minmax(430px,1fr) 250px;gap:15px;align-items:start}
.panel {
  background:linear-gradient(145deg,#1d2130,#171b27);border:1px solid #34394a;border-radius:10px;box-shadow:0 12px 35px #080a102e}
.hero-panel {
  padding:17px}
.hero-panel .panel-kicker {
  display:flex;justify-content:space-between;align-items:center}
.level-badge {
  color:var(--gold);border:1px solid #594d3e;border-radius:4px;padding:4px 6px;font-size:8px}
.hero-art {
  height:170px;margin:17px 0 13px;border:1px solid #3b3544;border-radius:7px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,#704a42 0,#2c2632 37%,#171a27 78%)}
.art-glow {
  position:absolute;width:130px;height:130px;border-radius:50%;left:50%;top:32px;transform:translateX(-50%);background:#d7825b1c;filter:blur(19px)}
.hero-sigil {
  position:absolute;left:50%;top:15px;transform:translateX(-50%);color:#e8bc7255;font-size:32px}
.hero-figure {
  position:absolute;inset:40px 0 0;display:flex;justify-content:center}
.hero-head {
  position:absolute;z-index:2;top:7px;width:28px;height:34px;border-radius:45% 45% 35% 35%;background:linear-gradient(90deg,#d9b795,#8b685f);box-shadow:0 0 10px #e8bc7244}
.hero-cape {
  position:absolute;top:27px;width:86px;height:94px;background:linear-gradient(100deg,#382c3a,#70504b 50%,#302733);clip-path:polygon(25% 0,75% 0,100% 100%,0 100%)}
.hero-body {
  position:absolute;top:35px;width:51px;height:67px;background:linear-gradient(90deg,#5b4a4b,#b38a69,#4b4148);clip-path:polygon(22% 0,78% 0,100% 100%,0 100%)}
.hero-blade {
